/** 
 * Constructs a  {@link SingletonAssert} for the value of the provided {@link PCollection} with thespecified reason. <p>Note that the actual value must be coded by a  {@link KvCoder}, not just any  {@code Coder<K,V>}.
 */
public static <K,V>SingletonAssert<Map<K,Iterable<V>>> thatMultimap(String reason,PCollection<KV<K,V>> actual){
  @SuppressWarnings("unchecked") KvCoder<K,V> kvCoder=(KvCoder<K,V>)actual.getCoder();
  return new PCollectionViewAssert<>(actual,View.asMultimap(),MapCoder.of(kvCoder.getKeyCoder(),IterableCoder.of(kvCoder.getValueCoder())),PAssertionSite.capture(reason));
}
